// api/icon.js — ícones do app (tela de início, notificação). Gerados a partir do ícone da aba.
// /api/icon?s=192 | s=512 | s=180 (iPhone) | s=512&m=1 (Android adaptável) | s=96&b=1 (ícone pequeno da notificação)
const I = {"180":"","192":"","512":"","m512":"","b96":""};
module.exports = (req, res) => {
  const q = req.query || {}, s = String(q.s || '192');
  const k = q.b ? 'b96' : q.m ? 'm512' : (I[s] ? s : '192');
  res.setHeader('Content-Type', 'image/png');
  res.setHeader('Cache-Control', 'public, max-age=604800');
  res.end(Buffer.from(I[k], 'base64'));
};
